function morphshape4(ctx,ctrans,frame,ratio,time){
	var pathData="M -2948 -2748 -256 -256 L -2948 -2748 264 264 -2776 2753 264 264 -2776 2753 -256 -256 -2948 -2748 -256 -256";
	ctx.fillStyle=tocolor(ctrans.apply([Math.round(255+ratio*(0)/65535),Math.round(255+ratio*(0)/65535),Math.round(0+ratio*(1)/65535),((Math.round(133+ratio*(0)/65535))/255)]));
	drawMorphPath(ctx,pathData,ratio,false);

	ctx.fill("evenodd");
	var pathData="M -2948 -2748 -256 -256 L -2776 2753 -256 -256 -2776 2753 264 264 -2948 -2748 264 264 -2948 -2748 -256 -256 Z";
	var scaleMode = "NORMAL";
	ctx.strokeStyle=tocolor(ctrans.apply([Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(1)/65535),((Math.round(0+ratio*(0)/65535))/255)]));
	ctx.lineWidth=0.0+ratio*(0)/65535;
	ctx.lineCap="round";
	ctx.lineJoin="round";
	drawMorphPath(ctx,pathData,ratio,true,scaleMode);

}

